// Des: Unit tests for scheduler core: tick, snapshot, re-arm, stop
// Flo: build Sche without threads > tick, snap, rearm, stop > assert
// I/O: Task specs + fake clock ms > pass or fail
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const supe = @import("tasksuper"); const tick = @import("tk-task-tick.zig");
const tszz = std.testing; const Sche = tick.Sche; const CF = tick.CF;
fn plusJson(allo: std.mem.Allocator, json: []const u8) std.json.Value { return std.json.parseFromSliceLeaky(std.json.Value, allo, json, .{}) catch unreachable; }
test "a fresh Sched reports empty, not ready" { var sche: Sche = .{}; sche.gpaz = tszz.allocator; try tszz.expect(!sche.read.load(.acquire)); try tszz.expectEqual(@as(u32, 0), sche.tick_coun.load(.monotonic)); }
test "tick increments the counter without a thread" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.tick(iozz); sche.tick(iozz); sche.tick(iozz); try tszz.expectEqual(@as(u32, 3), sche.tick_coun.load(.monotonic)); }
test "snapshot on an unloaded Sched is all zeroes, never a crash" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; const snap = sche.snap(iozz); try tszz.expectEqual(@as(usize, 0), snap.tota); try tszz.expectEqual(@as(usize, 0), snap.arme); try tszz.expect(!snap.rawz_okay); }
test "a re-arm keeps a spent boot task spent, and forgets a switched-off one" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; defer { var iter = sche.boot.keyIterator(); while (iter.next()) |keyz| sche.gpaz.free(keyz.*); sche.boot.deinit(sche.gpaz); } const nowz = time.localNow(); const task = stor.Task{ .id = "b1", .type = "boot", .run = "x" }; var first = [_]armz.Armed{try armz.armTask(task)}; sche.arme = &first; try tszz.expect(first[0].due(iozz, nowz, 1_000, null)); sche.bootNote("b1"); var secd = [_]armz.Armed{try armz.armTask(task)}; sche.arme = &secd; sche.runzStatCarr(iozz); try tszz.expect(!secd[0].due(iozz, nowz, 2_000, null)); sche.arme = sche.arme[0..0]; sche.runzStatCarr(iozz); try tszz.expect(!sche.boot.contains("b1")); var thrd = [_]armz.Armed{try armz.armTask(task)}; sche.arme = &thrd; sche.runzStatCarr(iozz); try tszz.expect(thrd[0].due(iozz, nowz, 3_000, null)); }
test "start then deinit: both threads stop before state is freed" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; try sche.star(tszz.allocator, iozz, ".zig-cache\\no-task-file-here"); try tszz.expect(sche.read.load(.acquire)); var wait: u32 = 0; while (sche.tick_coun.load(.monotonic) == 0 and wait < 3000) : (wait += 20) { std.Io.sleep(iozz, .fromMilliseconds(20), .awake) catch {}; } try tszz.expect(sche.tick_coun.load(.monotonic) > 0); sche.dein(); try tszz.expect(sche.stop.load(.acquire)); try tszz.expect(sche.exit.load(.acquire)); try tszz.expect(sche.prob_exit.load(.acquire)); try tszz.expectEqual(@as(usize, 0), sche.arme.len); try tszz.expect(sche.load == null); }
